def G(t):
    R=[("GPT-6.2","Джі-Пі-Ті шість два"),("ChatGPT","Чат Джі-Пі-Ті"),("Claude","Клод"),("Fable","Фейбл"),("Gemini 4 Neon","Джеміні чотири Неон"),("Neon","Неон"),("Astra","Астра"),("Sol","Сол"),
       ("Gemini","Джеміні"),("Google","Гугл"),("OpenAI","Оупен Ей-Ай"),("Anthropic","Антропік"),("Nasdaq","Насдак"),("ANT","Ей-Ен-Ті"),("The Guardian","Гардіан"),("Signal","Сігнал"),
       ("Android","Андроїд"),("iOS 27","Ай-Оу-Ес двадцять сім"),("iOS","Ай-Оу-Ес"),("iPhone","Айфон"),("Siri","Сірі"),("MacPaw","МакПо"),("Moonlock","Мунлок"),("AI Quests","Ей-Ай Квестс"),
       ("Frostbite","Фростбайт"),("Carbon","Карбон"),("Hydrogen","Гідроджен"),("Mac","Мак"),("QR","кью-ар"),("SMS","есемес"),("Architect Labs","Аркітект Лабс"),("Tasks","Таскс"),("Task","Таск"),("Chat","Чат"),("API","Ей-Пі-Ай"),("Pro","Про"),("Ultra","Ультра"),("AI Mode","Ей-Ай Мод")]
    for a,b in R: t=t.replace(a,b)
    t=re.sub(r"ШІ-(\w+)", r"\1 штучного інтелекту", t)
    for a,b in [("від ШІ","від штучного інтелекту"),("з ШІ","зі штучним інтелектом"),("на ШІ","на штучний інтелект"),("у ШІ","у штучний інтелект")]: t=t.replace(a,b)
    return t.replace("ШІ","штучний інтелект")

